class Camera {
    void takePicture() {
        System.out.println("Click!");
    }
}

class ProCamera extends Camera {
    @Override
    void takePicture() {
        System.out.println("High Resolution Click!!");
    }
}

public class Main {
    public static void main(String[] args) {
        Camera normal = new Camera();
        normal.takePicture();

        ProCamera pro = new ProCamera();
        pro.takePicture(); // 바뀐 게 실행됨

        // 다형성 (Polymorphism) 맛보기
        Camera poly = new ProCamera();
        poly.takePicture(); // ???
    }
}
